crd() { kubectl --context main get crd backups.ops.example.com -o jsonpath="$1" 2>/dev/null; }
check "v1 is served and is the storage version" bash -c "[ \"\$(kubectl --context main get crd backups.ops.example.com -o jsonpath='{.spec.versions[?(@.name==\"v1\")].served} {.spec.versions[?(@.name==\"v1\")].storage}')\" = 'true true' ]"
check "v1alpha1 is still served (deprecated), but no longer stored" bash -c "[ \"\$(kubectl --context main get crd backups.ops.example.com -o jsonpath='{.spec.versions[?(@.name==\"v1alpha1\")].served} {.spec.versions[?(@.name==\"v1alpha1\")].storage} {.spec.versions[?(@.name==\"v1alpha1\")].deprecated}')\" = 'true false true' ]"
check "Backup nightly (v1) exists with schedule '30 1 * * *' and retention 14" bash -c "[ \"\$(kubectl --context main -n ops-backup get backups.v1.ops.example.com nightly -o jsonpath='{.spec.schedule}|{.spec.retention}')\" = '30 1 * * *|14' ] && kubectl --context main get crd backups.ops.example.com -o jsonpath='{.status.storedVersions}' | grep -q '\"v1\"'"
check "legacy-weekly is still there and readable as v1" bash -c "[ \"\$(kubectl --context main -n ops-backup get backups.v1.ops.example.com legacy-weekly -o jsonpath='{.apiVersion} {.spec.retention}')\" = 'ops.example.com/v1 4' ]"
